def _validated_cfd_decision_items(items: object) -> list[dict]:
    """Validate the decision batch before any decision is parsed.

    The argument must be a non-empty list of dicts each holding exactly
    ``id`` (a non-empty str, unique across the batch) and ``decision``
    (bytes).  Container, element and field type faults raise
    :class:`TypeError`; an empty list, an empty or duplicate id or a
    wrong key set raises :class:`ValueError`.
    """
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if not items:
        raise ValueError("items must be a non-empty list")
    validated: list[dict] = []
    seen_ids: set[str] = set()
    for position, item in enumerate(items):
        where = f"item {position}"
        if not isinstance(item, dict):
            raise TypeError(f"{where} must be a dict")
        if set(item.keys()) != _CFD_DECISION_ITEM_KEYS:
            raise ValueError(
                f"{where} must contain exactly the keys 'decision' and 'id'"
            )
        item_id = item[ID]
        if not isinstance(item_id, str):
            raise TypeError(f"{where} id must be a str")
        if item_id == "":
            raise ValueError(f"{where} id must be non-empty")
        if item_id in seen_ids:
            raise ValueError(f"duplicate id {item_id!r}")
        seen_ids.add(item_id)
        decision = item[_CFD_DECISION]
        if not isinstance(decision, bytes):
            raise TypeError(f"{where} decision must be bytes")
        validated.append({ID: item_id, _CFD_DECISION: decision})
    return validated


def _cfd_decisions_item_report(
    item_id: str, status: str, error: str | None, result: dict | None
) -> dict:
    """One chain fork decision batch report with the fixed key order."""
    return {
        CHECKPOINT_ITEM_ERROR: error,
        ID: item_id,
        VERDICT_ITEM_RESULT: result,
        STATUS: status,
    }


def _verify_cfd_decision_item(
    item: dict,
    validated_prune_policy: dict,
    validated_site_policy: dict,
    validated_keyring: dict[str, list[dict]],
    moment: int,
) -> dict:
    """Verify one chain fork decision in isolation.

    Unknown, revoked, not-yet-valid or expired credentials and a wrong
    signature make the item ``unauthenticated``; every encoding,
    key-set, digest, ordering, tally or binding fault makes it
    ``invalid``; a passing decision is ``verified``.
    """
    item_id = item[ID]
    try:
        result = _verify_chain_fork_decision_core(
            item[_CFD_DECISION],
            validated_prune_policy,
            validated_site_policy,
            validated_keyring,
            moment,
        )
    except AuthenticationError as exc:
        return _cfd_decisions_item_report(
            item_id, _CFD_DECISIONS_UNAUTHENTICATED, str(exc), None
        )
    except (InvalidChainDecisionError, TypeError) as exc:
        # A TypeError here can only come from a wrong JSON field type
        # *inside* the decision bytes; the public argument types were

def _validated_pac_site_policy(policy: object) -> dict:
    """Validate a versioned prune-aggregate site policy into fresh form.

    The policy keeps the exact sites/threshold contract of
    :func:`_validated_prune_batch_site_policy` -- a non-empty mapping of
    each authorized non-empty site to its non-empty set of allowed
    positive key versions and a positive threshold no greater than the
    site count -- and additionally carries exactly a positive integer
    ``policyVersion``.  Type faults raise :class:`TypeError` (a
    :class:`bool` never poses as an int); key-set or value faults raise
    :class:`ValueError`.
    """
    if not isinstance(policy, dict):
        raise TypeError("site policy must be a dict")
    if set(policy.keys()) != _PAC_SITE_POLICY_KEYS:
        raise ValueError(
            "site policy must contain exactly the keys 'sites', "
            "'threshold' and 'policyVersion'"
        )
    policy_version = policy[DS_POLICY_VERSION]
    if isinstance(policy_version, bool) or not isinstance(policy_version, int):
        raise TypeError("site policy policyVersion must be an int")
    if policy_version <= 0:
        raise ValueError("site policy policyVersion must be a positive integer")
    base = _validated_prune_batch_site_policy({
        ADJ_SITES: policy[ADJ_SITES],
        ADJ_THRESHOLD: policy[ADJ_THRESHOLD],
    })
    base[DS_POLICY_VERSION] = policy_version
    return base


def _pac_site_policy_bytes(policy: dict) -> bytes:
    """Canonical compact bytes of the normalized versioned site policy.

    Sites are listed ascending with ascending version arrays and every
    key is recursively sorted; ``policyVersion`` is bound alongside.
    """
    return _prune_compact({
        ADJ_SITES: {
            site: sorted(policy[ADJ_SITES][site])
            for site in sorted(policy[ADJ_SITES])
        },
        ADJ_THRESHOLD: policy[ADJ_THRESHOLD],
        DS_POLICY_VERSION: policy[DS_POLICY_VERSION],
    })


def _pac_policy_digest(policy: dict) -> str:
    """SHA-256 of the canonical versioned site policy."""
    return hashlib.sha256(_pac_site_policy_bytes(policy)).hexdigest()


def _pac_plain_site_policy(policy: dict) -> dict:
    """The unversioned ``{sites, threshold}`` form a root aggregate binds."""
    return {ADJ_SITES: policy[ADJ_SITES], ADJ_THRESHOLD: policy[ADJ_THRESHOLD]}


